  for (const [x, z, w, d] of [
    [(fp.x0 + fp.x1) / 2, fp.z0, fp.x1 - fp.x0, t],
    [(fp.x0 + fp.x1) / 2, fp.z1, fp.x1 - fp.x0, t],
    [fp.x0, (fp.z0 + fp.z1) / 2, t, fp.z1 - fp.z0],
