+  await outside('out_south_f3', 0, 34, 0, 0.95, 8.0);
+  await outside('out_east', 36, 0, Math.PI / 2, 0.30, 4.2);
+
+  // the rooms behind those windows
+  await inside('in_ff2_11_bedroom5_south', 'FF2-11', 0);       // looks at z = +11
+  await inside('in_ff2_03_master_north', 'FF2-03', Math.PI);   // looks at z = -11
+  await inside('in_ff3_06_master_suite_south', 'FF3-06', 0);
+  await inside('in_gf_14_foyer_entrance', 'GF-14', 0);
+
+  console.log(JSON.stringify(rows, null, 1));
+  await browser.close();
+})().catch((e) => { console.error(e); process.exit(1); });
