    const cam = w.camera;
    const W = window.innerWidth, H = window.innerHeight;
    const ray = new T.Raycaster();
    const at = (nx, ny) => {
      ray.setFromCamera(new T.Vector2(nx, ny), cam);
      return ray.intersectObjects(w.scene.children, true).slice(0, 3)
