      if (!m) continue;
      const bb = new T.Box3().setFromObject(m);
      box[n] = {
        min: bb.min.toArray().map((v) => +v.toFixed(1)),
        max: bb.max.toArray().map((v) => +v.toFixed(1)),
        tris: (m.geometry.index ? m.geometry.index.count : m.geometry.attributes.position.count) / 3,
      };
