  const p = await b.newPage({ viewport: { width: 1280, height: 720 } });
  await p.goto('http://127.0.0.1:5333/?probe=1');
  await p.waitForFunction(() => window.__silid?.ready, null, { timeout: 180000 });
  const out = await p.evaluate(() => {
    const w = window.__silid, T = w.THREE;
    w.spawnAt(0, 62, null, 0, 0.22);
    w.player.flashlightOn = false; if (w.player.flash) w.player.flash.visible = false;
    w.game._lightTimer = 0; w.game.update(0.05);
    w.scene.updateMatrixWorld(true);
    const ray = new T.Raycaster();
    const probe = (nx, ny) => {
      ray.setFromCamera(new T.Vector2(nx, ny), w.camera);
      return ray.intersectObjects(w.scene.children, true).slice(0, 4)
        .map((h) => ({ n: h.object.name || h.object.type, d: +h.distance.toFixed(2), p: h.point.toArray().map((v) => +v.toFixed(2)) }));
    };
    const res = { centre: probe(-0.003, -0.139), up: probe(-0.003, -0.08), down: probe(-0.003, -0.20) };
    const m = w.scene.getObjectByName('FacadeShell');
    res.shellMap = m ? { aniso: m.material.map?.anisotropy, repeat: m.material.map?.repeat?.toArray(), rough: !!m.material.roughnessMap, normal: !!m.material.normalMap, ao: !!m.material.aoMap } : null;
    return res;
  });
  console.log(JSON.stringify(out, null, 2));
  await b.close();
})().catch((e) => { console.error(e); process.exit(1); });
