      const x = cx + nx * side, zz = z + nz * side;
      pos.push(x, heightAt(x, zz) + lift, zz);
      uv.push(side, zz);   // metres — the material carries the tile size
    }
    if (i < steps) {
      for (let j = 0; j < cols - 1; j++) {
