// gust begins. `setWind` replaces the whole state; `tickWind` advances the
// phase and returns the current amplitude so the caller never has to hold
// its own copy.
export let wind = { dir: new THREE.Vector2(1, 0), strength: 0, period: 4.5 };

export function getWind() { return wind; }

export function setWind(d, s, p) {
  wind = { dir: d ? new THREE.Vector2(d.x, d.y).normalize() : new THREE.Vector2(1, 0),
           strength: s ?? 0, period: p ?? 4.5 };
}

export function tickWind(dt) {
  const w = wind;
  const g = 0.16 + 0.12 * Math.sin(windSeconds * 0.12);
  windSeconds += dt;
  if (windSeconds > w.period) windSeconds -= w.period;
  const t = windSeconds / w.period;
  // A rounded sine: the forest sits at zero, a gust builds through the
  // quarter, sinks through the three-quarter and returns to still. The
  // frequency is deliberately low for a humid, still afternoon.
  const s = w.strength * Math.sin(Math.PI * t) * Math.sin(Math.PI * t);
  return s;
}

export function updateWind(seconds) {
  windSeconds = seconds;
  for (const u of windUniforms) u.uWindTime.value = seconds;
}

export function windTime() { return windSeconds; }

// Probe surface: how many materials carry the wind program, at what phase, and
