  [54.4, 6.0, -2.01, 56.2, 6.0, '06_service_door', 'the service door at the end of the route, with its prompt'],
  [70.4, 7.9, 0.78, 60.0, 7.9, '07_forest_emergence', 'standing in the forest, looking back at the concealed exit'],
];

