+scene.add(new THREE.HemisphereLight(0xbfc7d4, 0x40382c, 1.2));
+const key = new THREE.DirectionalLight(0xffffff, 1.6); key.position.set(4, 8, 6); scene.add(key);
+const fill = new THREE.DirectionalLight(0x99a8c0, 0.8); fill.position.set(-6, 4, -5); scene.add(fill);
+
+const hud = document.getElementById('hud');
+const api = { ready: false, info: null, setCam: null, bbox: null, materials: null, grid: null };
+window.__room = api;
+
+const params = new URLSearchParams(location.search);
+const file = params.get('f');
+const loader = new GLTFLoader();
+loader.load(file, (gltf) => {
+  const root = gltf.scene;
+  scene.add(root);
+  const box = new THREE.Box3().setFromObject(root);
+  const size = box.getSize(new THREE.Vector3());
+  const center = box.getCenter(new THREE.Vector3());
+  let meshes = 0, tris = 0;
+  const mats = new Map();
+  const imgs = new Map();
+  root.traverse((o) => {
+    if (!o.isMesh) return;
+    meshes++;
+    const g = o.geometry;
+    tris += (g.index ? g.index.count : g.attributes.position.count) / 3;
+    for (const m of (Array.isArray(o.material) ? o.material : [o.material])) {
+      if (!m) continue;
+      if (!mats.has(m.uuid)) mats.set(m.uuid, { name: m.name, type: m.type, side: m.side, transparent: m.transparent, opacity: m.opacity, maps: [] });
+      const rec = mats.get(m.uuid);
+      for (const k of ['map', 'normalMap', 'roughnessMap', 'metalnessMap', 'emissiveMap', 'aoMap']) {
+        const t = m[k];
+        if (!t) continue;
+        const im = t.image;
+        rec.maps.push(`${k}:${t.colorSpace}/${im ? im.width + 'x' + im.height : '?'}/${t.flipY ? 'flipY' : 'noflip'}`);
+        if (im) imgs.set((im.src || '').slice(-40) || im.width + 'x' + im.height, `${im.width}x${im.height}`);
+      }
+    }
+  });
+  api.bbox = { min: box.min.toArray(), max: box.max.toArray(), size: size.toArray(), center: center.toArray() };
+  api.materials = [...mats.values()];
+  api.info = { meshes, tris: Math.round(tris), materials: mats.size, images: imgs.size, size: size.toArray().map((v) => +v.toFixed(2)) };
+  hud.textContent = `${file}\nmeshes ${meshes} tris ${Math.round(tris)} mats ${mats.size}\nsize ${size.toArray().map((v) => v.toFixed(2)).join(' x ')}\nmin ${box.min.toArray().map((v) => v.toFixed(2)).join(',')}`;
+
+  // camera helper: look from `from` toward `at`
+  api.setCam = (from, at, fov) => {
+    cam.fov = fov || 60;
+    cam.updateProjectionMatrix();
+    cam.position.set(...from);
+    cam.lookAt(new THREE.Vector3(...at));
+    renderer.render(scene, cam);
+  };
+  // guides: world axes so rotation is readable, plus a 1 m floor grid
+  const axes = new THREE.AxesHelper(Math.max(size.x, size.z) * 0.6);
+  axes.position.set(center.x, box.min.y + 0.02, center.z);
+  scene.add(axes);
+  const grid = new THREE.GridHelper(Math.max(size.x, size.z) * 2, Math.round(Math.max(size.x, size.z) * 2), 0x335577, 0x223344);
+  grid.position.set(center.x, box.min.y + 0.01, center.z);
+  scene.add(grid);
+
+  api.setCam([center.x + size.x, center.y + size.y * 0.5, center.z + size.z], center.toArray(), 55);
+  api.ready = true;
+}, undefined, (e) => { hud.textContent = 'LOAD ERROR ' + (e?.message || e); api.error = String(e?.message || e); });
+
+function loop() { renderer.render(scene, cam); requestAnimationFrame(loop); }
+loop();
+</script>
+</body>
