{"kind":"tool","id":"jB6kO71WFbo","toolName":"write_file","input":{"path":"scripts/roof_route.cjs","content":"// Drive the roof route through the real controller, frame by frame, so the test
// does not depend on how slowly the software renderer draws. player.update() is
// the same code the frame loop calls; game.interact() is the same code the E
// key calls.
const { chromium } = require('playwright');

(async () => {
  const browser = await chromium.launch({ headless: true });
  const page = await browser.newPage({ viewport: { width: 480, height: 270 } });
  const errs = [];
  page.on('pageerror', (e) => errs.push('pageerror ' + e.message));
  await page.goto('http://127.0.0.1:5199/?probe=1');
  await page.waitForFunction(() => window.__silid?.ready, null, { timeout: 300000 });

  const out = await page.evaluate(() => {
    const w = window.__silid;
    const p = w.player;
    const g = w.game;
    const log = [];
    const snap = (tag) => log.push(tag + ' ' + JSON.stringify({
      foot: +p.footY.toFixed(2), x: +p.pos.x.toFixed(2), z: +p.pos.z.toFixed(2),
      climbing: p.isClimbing, yaw: +p.yaw.toFixed(2),
    }));
    const frames = (n, keys = {}) => {
      for (let i = 0; i < n; i++) {
        Object.assign(p.keys, { KeyW: false, KeyS: false }, keys);
        p.update(1 / 60, g);
      }
      Object.assign(p.keys, { KeyW: false, KeyS: false });
    };
    const aim = () => {
      const t = g.nearestInteraction();
      return t ? t.kind + ':' + (t.dir || '') : null;
    };

    // 1. at the foot, facing the wall
    w.spawnAt(-12.5, -12.3, 0, Math.PI, 0);
    p.enabled = true;
    frames(2);
    snap('base');
    log.push('aim base ' + aim());

    // 2. E
    g.interact();
    snap('climb start');
    const t0 = p.climbTarget;
    // duplicate E while climbing must not restart the climb
    g.interact();
    log.push('duplicate E kept target ' + (p.climbTarget === t0));

    // 3. W all the way up
    frames(420, { KeyW: true });
    snap('top');

    // 4. the door at the head of the landing
    log.push('aim top ' + aim());
    g.interact();
    const door = w.architecture.doors.find((d) => d.y > 11 && Math.abs((d.at ?? 0) + 12.5) < 0.3);
    log.push('door ' + JSON.stringify(door ? { open: door.open, at: door.at, w: door.w, y: door.y } : null));

    // 5. through onto the deck
    p.yaw = Math.PI; p.pitch = 0; p.syncCamera();
    frames(150, { KeyW: true });
    snap('deck');

    // 6. turn round and walk back to the landing
    p.yaw = 0; p.syncCamera();
    frames(150, { KeyW: true });
    snap('back');

    // 7. face the ladder and climb down
    p.yaw = Math.PI; p.syncCamera();
    frames(2);
    log.push('aim ladder ' + aim());
    g.interact();
    snap('down start');
    frames(480, { KeyS: true });
    snap('bottom');
    return log;
  });
  for (const line of out) console.log(line);
  console.log('errors', JSON.stringify(errs.slice(0, 4)));
  await browser.close();
})();
"}}


