{"kind":"tool","id":"jDmU29aC63M","toolName":"write_file","input":{"path":"scripts/roof_shots2.cjs","instructions":"Create a fast canvas-readback screenshot script for the roof route.","content":"// Photograph the roof route from the running game. Each frame is posed, then
// rendered and read back from the live canvas in the same task, so it is a real
// frame of the real scene rather than a mock-up. (The software renderer takes
// ~a second per frame, so the ordinary screenshot path times out.)
const { chromium } = require('playwright');
const fs = require('fs');

const URL = process.env.SILID_URL || 'http://127.0.0.1:5333/';
const OUT = 'reports/roof';

(async () => {
  fs.mkdirSync(OUT, { recursive: true });
  const browser = await chromium.launch({ headless: true });
  const page = await browser.newPage({ viewport: { width: 960, height: 540 } });
  await page.goto(URL + '?probe=1');
  await page.waitForFunction(() => window.__silid?.ready, null, { timeout: 300000 });

  const shot = async (name, setup) => {
    const data = await page.evaluate((code) => {
      const w = window.__silid;
      // eslint-disable-next-line no-new-func
      new Function('w', code)(w);
      w.renderer.render(w.scene, w.camera);
      return w.renderer.domElement.toDataURL('image/png');
    }, setup);
    fs.writeFileSync(`${OUT}/${name}.png`, Buffer.from(data.split(',')[1], 'base64'));
    console.log(name);
  };

  // 1. the foot of the ladder, from the yard
  await shot('01_ladder_base', `
    w.spawnAt(-13.3, -14.4, 0, Math.PI + 0.12, 0.34);
    w.player.syncCamera();
  `);
  // 2. mid-climb: a body on the rungs, six metres up
  await shot('02_climb_mid', `
    const p = w.player;
    p.footY = 6.2; p.pos.set(-13.3, p.footY + p.height, -11.42);
    p.yaw = Math.PI; p.pitch = 0.06; p.syncCamera();
  `);
  // 3. standing on the landing at the head of the ladder, facing the door
  await shot('03_landing_door', `
    w.spawnAt(-12.2, -11.75, 11.6, Math.PI, 0.02);
  `);
  // 4. through the door, looking back out over the landing
  await shot('04_doorway_out', `
    w.spawnAt(-12.2, -10.5, 11.6, 0, -0.06);
  `);
  // 5. the roof deck the door opens onto
  await shot('05_roof_deck', `
    w.spawnAt(-12.0, -8.4, 11.6, Math.PI * 1.12, -0.02);
  `);
  // 6. back at the foot after the descent, looking up
  await shot('06_bottom', `
    w.spawnAt(-13.3, -12.15, 0, Math.PI, 0.55);
  `);

  await browser.close();
})();
"}}


