// that deal with real-world surfaces.
//
// `nudge` is an optional whole-tile count pushed from a room plan so a parquet
// strip or a tile row can start its next tile boundary at a sensible joint
// without any other floor that shares the base material also shifting. When it
// is supplied the maps keep the metre-based repeat; the tail offset is applied
export function tileAtMetres(mat, metres, nudge = 0) {
  const r = 1 / Math.max(0.05, metres);
  for (const k of ['map', 'normalMap', 'roughnessMap']) {
    if (!mat[k]) continue;
    // material.clone() copies the map REFERENCES, so setting a repeat on a
    // clone silently rewrites the tiling of every other mesh using the same
    // texture — and is rewritten by whichever code calls tileMaps last. Any
    // material that is being given its own real-world scale must own its maps.
    if (!mat.userData.uvOwned) {
      mat[k] = mat[k].clone();
      mat[k].needsUpdate = true;
    }
    mat[k].repeat.set(r, r);
    mat[k].needsUpdate = true;
  }
  mat.userData.uvOwned = true;
  mat.userData.uvNudge = nudge;
  return mat;
}","allowMultiple":false}]}}
